  "AR pictures are illustrations; the look on your phone depends on your camera and room. AR crackers on your real floor need a phone that supports Google Play Services for AR.": "AR-Bilder sind Illustrationen; wie es auf deinem Handy aussieht, hängt von Kamera und Raum ab. AR-Böller auf deinem echten Boden brauchen ein Handy, das Google Play-Dienste für AR unterstützt.",
  "15 landmarks in 3D, look around": "15 Wahrzeichen in 3D, schau dich um",
  "2D & 3D": "2D & 3D",
