  "New card": "Neue Karte",
  "Cards you make are kept here, ready to play, change or send again.": "Deine Karten werden hier aufbewahrt, bereit zum Abspielen, Ändern oder erneuten Senden.",
  "Cards friends send you are kept here, so you can watch them again.": "Karten von Freunden werden hier aufbewahrt, damit du sie nochmal ansehen kannst.",
