  "Eid": "Eid",
  "Eid Mubarak": "Eid Mubarak",
  "May this Eid bring you peace, happiness and countless blessings. Eid Mubarak!": "Möge dir dieses Eid Frieden, Glück und unzählige Segen bringen. Eid Mubarak!",
