  "Out of every sky I've seen, you're still the brightest light in mine.": "Von allen Himmeln, die ich je sah, bist du immer noch das hellste Licht in meinem.",
  "I love that home stopped being a place the day it became you.": "Ich liebe, dass Zuhause kein Ort mehr ist, seit es du bist.",
  "Every firework fades. What I feel for you only gets louder.": "Jedes Feuerwerk verblasst. Was ich für dich fühle, wird nur lauter.",
  "I'd choose you on every Diwali, in every lifetime.": "Ich würde dich an jedem Diwali wählen, in jedem Leben.",
  "You're the reason ordinary nights feel like festivals.": "Wegen dir fühlen sich normale Nächte wie Feste an.",
  "I love you because with you, even silence feels like…": "Ich liebe dich, weil sich mit dir sogar Stille anfühlt wie…",
  "Warning: you make my heart burst louder than a thousand-wala.": "Achtung: Mein Herz knallt bei dir lauter als ein Tausender-Böller.",
  "Are you a sparkler? You light me up every time you smile.": "Bist du eine Wunderkerze? Du bringst mich jedes Mal zum Leuchten, wenn du lächelst.",
  "I lost my words the first time you smiled. Still looking for them.": "Als du das erste Mal gelächelt hast, fehlten mir die Worte. Ich suche sie immer noch.",
  "You, me and a rooftop full of fireworks. Say yes?": "Du, ich und ein Dach voller Feuerwerk. Sagst du ja?",
  "My favourite view tonight isn't the fireworks. It's you.": "Mein schönster Anblick heute Nacht ist nicht das Feuerwerk. Sondern du.",
  "The first thing I noticed about you was…": "Das Erste, was mir an dir auffiel, war…",
  "You make my bad days shorter and my good days shine.": "Du machst meine schlechten Tage kürzer und meine guten strahlender.",
  "I love the way you laugh before you finish your own jokes.": "Ich liebe, wie du lachst, bevor du deine eigenen Witze zu Ende erzählst.",
  "Thank you for being my safe place in a noisy world.": "Danke, dass du mein sicherer Ort in einer lauten Welt bist.",
  "Your hug is my favourite place to be.": "Deine Umarmung ist mein Lieblingsort.",
  "With you, every day is a little Diwali.": "Mit dir ist jeder Tag ein kleines Diwali.",
  "I love the little things you do, like…": "Ich liebe die kleinen Dinge, die du tust, wie…",
  "I love you more than free gems. And that's a lot.": "Ich liebe dich mehr als Gratis-Edelsteine. Und das will was heißen.",
  "You're my favourite notification.": "Du bist meine Lieblingsbenachrichtigung.",
  "I love you even when you steal the last laddoo.": "Ich liebe dich sogar, wenn du das letzte Laddoo klaust.",
  "You're the only one I'd share my phuljhari with.": "Du bist die/der Einzige, mit der/dem ich meine Phuljhari teilen würde.",
  "Life with you is like a cracker: loud, bright and a little dangerous.": "Das Leben mit dir ist wie ein Böller: laut, hell und ein bisschen gefährlich.",
  "I love you because you laugh at my worst jokes, like…": "Ich liebe dich, weil du über meine schlechtesten Witze lachst, wie…",
  "Amma, every light in my life started with you.": "Mama, jedes Licht in meinem Leben hat mit dir angefangen.",
  "Thank you for believing in me before I believed in myself.": "Danke, dass du an mich geglaubt hast, bevor ich es tat.",
  "You gave me roots, and then you gave me wings.": "Du hast mir Wurzeln gegeben, und dann Flügel.",
  "Friends like you make every festival feel like home.": "Freunde wie du lassen jedes Fest wie Zuhause wirken.",
  "Whatever I become, it began with your love.": "Was auch immer aus mir wird, es begann mit deiner Liebe.",
  "I'm grateful for you because…": "Ich bin dankbar für dich, weil…",
