  "The Silver Peacock Lamp": "Die Silberne Pfauenlampe",
  "Thieves took the temple’s silver peacock lamp. Follow the jasmine trail and bring it back": "Diebe haben die silberne Pfauenlampe des Tempels gestohlen. Folge der Jasminspur und bring sie zurück",
  "Lamps for Madurai": "Lampen für Madurai",
  "Madurai’s temple street is full of lamps tonight, and the silver peacock lamp is the brightest.": "Madurais Tempelstraße ist heute Nacht voller Lampen, und die silberne Pfauenlampe ist die hellste.",
  "The peacock lamp is gone!": "Die Pfauenlampe ist weg!",
  "Thieves have taken the silver peacock lamp and slipped into the flower market.": "Diebe haben die silberne Pfauenlampe genommen und sind in den Blumenmarkt entwischt.",
  "Follow the jasmine": "Folge dem Jasmin",
  "Light crackers to see in the dark. Follow the clues: jasmine petals, an anklet bell, a flower basket.": "Zünde Böller, um im Dunkeln zu sehen. Folge den Hinweisen: Jasminblüten, ein Fußkettchen-Glöckchen, ein Blumenkorb.",
  "Bring it back": "Bring sie zurück",
