  "🦚 The silver peacock lamp is gone! Light a cracker by the dark patch to find the jasmine trail": "🦚 Die silberne Pfauenlampe ist weg! Zünde einen Böller an der dunklen Stelle, um die Jasminspur zu finden",
  "🚨 Seth-ji thinks YOU are the thief! Run the peacock lamp to the temple steps 🛕": "🚨 Seth-ji hält DICH für den Dieb! Bring die Pfauenlampe zu den Tempelstufen 🛕",
