  "You followed the jasmine petals, the anklet bell and the flower basket, and brought the silver peacock lamp back to the temple steps.": "Du bist den Jasminblüten, dem Fußkettchen-Glöckchen und dem Blumenkorb gefolgt und hast die silberne Pfauenlampe zurück zu den Tempelstufen gebracht.",
  "I brought the silver peacock lamp home to the temple in Fireworks Street!": "Ich habe die silberne Pfauenlampe in der Fireworks Street zum Tempel heimgebracht!",
  "Light up the jasmine trail": "Erleuchte die Jasminspur",
