  "Search the flower basket": "Durchsuche den Blumenkorb",
  "Under the jasmine in a flower-seller’s basket: the silver peacock lamp!": "Unter dem Jasmin im Korb einer Blumenhändlerin: die silberne Pfauenlampe!",
  "The Golden Deepam Lamp": "Die Goldene Deepam-Lampe",
