  "Birthdays are read from your contacts on this phone only. Nothing is uploaded.": "Geburtstage werden nur aus den Kontakten auf diesem Handy gelesen. Nichts wird hochgeladen.",
  "Next, your phone asks to let the app read your contacts and, if you like, your calendar: only the names, birthdays and photos of people with a birthday, and the birthdays in your Google Birthdays calendar. You pick who to add, and they stay on this phone. Not now keeps everything else working.": "Als Nächstes fragt dein Handy, ob die App deine Kontakte und, wenn du magst, deinen Kalender lesen darf: nur Namen, Geburtstage und Fotos von Personen mit Geburtstag sowie die Geburtstage in deinem Google-Geburtstagskalender. Du wählst, wen du hinzufügst, und sie bleiben auf diesem Handy. Mit Jetzt nicht funktioniert alles andere weiter.",
  "Remind me on their birthday": "Am Geburtstag erinnern",
  "Allow notifications and the app reminds you the day before and on the morning of each birthday. The reminders are made on this phone; nothing is sent anywhere.": "Erlaube Benachrichtigungen, dann erinnert dich die App am Vortag und am Morgen jedes Geburtstags. Die Erinnerungen entstehen auf diesem Handy, nichts wird irgendwohin gesendet.",
