  "Happy Children’s Day": "Alles Gute zum Kindertag",
  "Happy Karthigai Deepam": "Frohes Karthigai Deepam",
  "May this Vishu fill your year with light, plenty and golden konna flowers.": "Möge dieses Vishu dein Jahr mit Licht, Fülle und goldenen Konna-Blüten füllen.",
  "May good always win over evil in your life. Happy Dussehra!": "Möge in deinem Leben das Gute immer über das Böse siegen. Frohes Dussehra!",
  "Stay curious, keep laughing and never stop shining. Happy Children’s Day!": "Bleib neugierig, lach viel und hör nie auf zu strahlen. Alles Gute zum Kindertag!",
  "Drag the sparkler here, onto a cracker’s fuse": "Zieh die Wunderkerze hierher, auf die Zündschnur eines Böllers",
  "Tap Fire to light your first firework": "Tippe auf Zünden für dein erstes Feuerwerk",
  "Tap a cracker to place it on the street": "Tippe auf einen Böller, um ihn auf die Straße zu stellen",
  "Now sweep the sparkler across the fuses": "Streich jetzt mit der Wunderkerze über die Zündschnüre",
  "Tap Fire": "Tippe auf Zünden",
  "Trace here: draw with your finger to write in light": "Hier nachzeichnen: Schreib mit dem Finger in Licht",
  "Your turn: tap here to light this sky yourself": "Du bist dran: Tippe hier, um diesen Himmel selbst zu erleuchten",
  "Tap here to start: burst the lanterns as they rise": "Tippe hier zum Start: Lass die Laternen beim Aufsteigen platzen",
  "Tap here to play level 1": "Tippe hier, um Level 1 zu spielen",
  "Tap here: fire your crackers and beat your friend": "Tippe hier: Zünde deine Böller und schlag deinen Freund",
  "Tap here to add a birthday": "Tippe hier, um einen Geburtstag hinzuzufügen",
  "Type their name here": "Gib hier den Namen ein",
  "Write who you are grateful for today": "Schreib, wem du heute dankbar bist",
  "Tap here to light them up": "Tippe hier, um sie zu erleuchten",
  "Tap a wallpaper to set it": "Tippe auf einen Hintergrund, um ihn festzulegen",
  "Start here": "Starte hier",
  "Fire your first cracker": "Zünde deinen ersten Böller",
  "Drag the sparkler onto a cracker’s fuse. On a TV or computer, tap Fire.": "Zieh die Wunderkerze auf die Zündschnur eines Böllers. Am Fernseher oder Computer tippe auf Zünden.",
  "Your first win! The sky is proud of you ✨": "Dein erster Sieg! Der Himmel ist stolz auf dich ✨",
  "Your first firework! Happy Diwali ✨": "Dein erstes Feuerwerk! Happy Diwali ✨",
  "Your first card is ready. Someone is going to smile 💌": "Deine erste Karte ist fertig. Jemand wird lächeln 💌",
  "Your first wish is lit. Gratitude glows ✨": "Dein erster Wunsch leuchtet. Dankbarkeit strahlt ✨",
  "Hold the sparkler and drag it to a cracker’s fuse": "Halte die Wunderkerze und zieh sie zur Zündschnur eines Böllers",
  "Tap here to play the next level": "Tippe hier, um das nächste Level zu spielen",
