  "Everything you lit up, day by day. Kept on this phone only.": "Alles, was du erleuchtet hast, Tag für Tag. Nur auf diesem Handy gespeichert.",
  "Your sky is still dark": "Dein Himmel ist noch dunkel",
  "Make a love card or light someone up, and it shows here, day by day.": "Erstelle eine Liebeskarte oder erleuchte jemanden, dann erscheint es hier, Tag für Tag.",
